    'app/globals.css': textwrap.dedent('''
        @tailwind base;
        @tailwind components;
        @tailwind utilities;
    '''),
    'app/layout.tsx': textwrap.dedent('''
        import './globals.css'
        import type { Metadata } from 'next'
        export const metadata: Metadata = { title: 'EaseMize Chat', description: 'Chat UI demo' }
        export default function RootLayout({ children }: { children: React.ReactNode }) {
          return (
            <html lang="en">
              <body className="bg-gray-100 min-h-screen flex items-center justify-center">
                {children}
              </body>
            </html>
          )
        }
    '''),
    'app/page.tsx': textwrap.dedent('''
        import ChatLayout from '../components/ChatLayout'
        export default function HomePage() {
          return <ChatLayout />
        }
    '''),
    'components/ChatLayout.tsx': textwrap.dedent('''
        "use client"
        import { useState, useEffect } from 'react'
        import ChatSidebar from './ChatSidebar'
        import MessageList from './MessageList'
        import PromptInput from './PromptInput'
        import EmptyState from './EmptyState'

        interface Message { role: 'user' | 'assistant'; content: string }

        export default function ChatLayout() {
          const [messages, setMessages] = useState<Message[]>([])
          const [input, setInput] = useState('')
          const [streaming, setStreaming] = useState(false)
          const [assistantBuffer, setAssistantBuffer] = useState('')

          const addMessage = (msg: Message) => setMessages(prev => [...prev, msg])

          const handleSend = () => {
            if (!input.trim()) return
            const userMsg = { role: 'user', content: input }
            addMessage(userMsg)
            setInput('')
            // start mock streaming response
            setStreaming(true)
            setAssistantBuffer('')
          }

          // mock streaming effect
          useEffect(() => {
            if (streaming) {
              const reply = "Hello, this is a mock streaming assistant reply. It appears character by character."
              let idx = 0
              const interval = setInterval(() => {
                idx++
                setAssistantBuffer(reply.slice(0, idx))
                if (idx >= reply.length) {
                  clearInterval(interval)
                  addMessage({ role: 'assistant', content: reply })
                  setStreaming(false)
                }
              }, 50)
              return () => clearInterval(interval)
            }
          }, [streaming])

          return (
            <div className="flex w-full max-w-4xl h-[80vh] bg-white shadow-lg rounded-lg overflow-hidden">
              <ChatSidebar />
              <div className="flex flex-col flex-1">
                {messages.length === 0 && !streaming ? (
                  <EmptyState />
                ) : (
                  <MessageList messages={messages} />
                )}
                {streaming && <MessageList messages={[...messages, { role: 'assistant', content: assistantBuffer }]} />}
                <PromptInput value={input} onChange={setInput} onSend={handleSend} />
              </div>
            </div>
          )
        }
    '''),
    'components/ChatSidebar.tsx': textwrap.dedent('''
        "use client"
        export default function ChatSidebar() {
          return (
            <div className="w-64 bg-gray-200 p-4 overflow-y-auto">
              <h2 className="text-lg font-bold mb-2">Conversations</h2>
              <ul>
                <li className="text-gray-600">New Chat</li>
              </ul>
            </div>
          )
        }
    '''),
    'components/EmptyState.tsx': textwrap.dedent('''
        "use client"
        export default function EmptyState() {
          return (
            <div className="flex-1 flex items-center justify-center text-center p-8">
              <p className="text-gray-500">Start a conversation by typing below.</p>
            </div>
          )
        }
    '''),
    'components/MessageList.tsx': textwrap.dedent('''
        "use client"
        import React from 'react'
        import MarkdownRenderer from './MarkdownRenderer'
        interface Props { messages: { role: string; content: string }[] }
        export default function MessageList({ messages }: Props) {
          return (
            <div className="flex-1 overflow-y-auto p-4 space-y-4">
              {messages.map((msg, i) => (
                <div key={i} className={msg.role === 'user' ? 'text-right' : 'text-left'}>
                  <div className={msg.role === 'user' ? 'inline-block bg-blue-500 text-white rounded px-3 py-1' : 'inline-block bg-gray-300 text-gray-800 rounded px-3 py-1'}>
                    <MarkdownRenderer>{msg.content}</MarkdownRenderer>
                  </div>
                </div>
              ))}
            </div>
          )
        }
    '''),
    'components/PromptInput.tsx': textwrap.dedent('''
        "use client"
        interface Props { value: string; onChange: (v: string) => void; onSend: () => void }
        export default function PromptInput({ value, onChange, onSend }: Props) {
          return (
            <div className="p-4 border-t flex gap-2 items-center">
              <input
                className="flex-1 border rounded px-3 py-2"
                type="text"
                placeholder="Type a message..."
                value={value}
                onChange={e => onChange(e.target.value)}
                onKeyDown={e => { if (e.key === 'Enter') onSend() }}
              />
              <button className="bg-blue-600 text-white px-4 py-2 rounded" onClick={onSend}>Send</button>
            </div>
          )
        }
    '''),
    'components/MarkdownRenderer.tsx': textwrap.dedent('''
        "use client"
        import ReactMarkdown from 'react-markdown'
        export default function MarkdownRenderer({ children }: { children: string }) {
          return <ReactMarkdown>{children}</ReactMarkdown>
        }
    '''),
}

for path, content in files.items():
    # Use the write_file tool provided by the environment
    # The tool is accessible as a global function write_file
    write_file({"path": path, "content": content})

print('done')

